function getData(cache, key, cb) {
  if (Object.prototype.hasOwnProperty.call(cache, key)) {
    cb(cache[key]); // 命中快取：同步呼叫
  } else {
    setTimeout(function () {
      cb('fetched:' + key); // 沒命中：非同步呼叫
    }, 0);
  }
}
var cache = { a: 'cached-a' };
console.log('before');
getData(cache, 'a', function (result) {
  console.log('callback:', result);
});
console.log('after');

